/* ---------- UI utilitaires ---------- */
function toast(m,k='ok'){const e=document.createElement('div');e.className='toast '+k;e.textContent=m;$('#toast').appendChild(e);setTimeout(()=>e.remove(),3500)}
const dlg=(h,c='')=>{$('#modal').innerHTML=`<div class="ov"><div class="dlg ${c}">${h}</div></div>`},close=()=>{$('#modal').innerHTML=''};
const ask=(msg,fn)=>{pend=fn;dlg(`<h3>Confirmation</h3><p>${msg}</p><div class="row"><button class="btn ghost" data-a="close">Annuler</button><button class="btn ko" data-a="yes">Confirmer</button></div>`)};
function dl(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{a.remove();URL.revokeObjectURL(a.href)},4000);toast('Fichier enregistré : '+name)}
const fname=r=>`Rapport_${r.client.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\W+/g,'_')}_${r.start.replace(/\//g,'-')}`;
const compress=(f,m=1280,q=.72)=>new Promise(res=>{const u=URL.createObjectURL(f),im=new Image();im.onload=()=>{const k=Math.min(1,m/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);c.getContext('2d').drawImage(im,0,0,c.width,c.height);URL.revokeObjectURL(u);res({d:c.toDataURL('image/jpeg',q),w:c.width,h:c.height})};im.onerror=()=>res(null);im.src=u});

