document.addEventListener('input',e=>{const t=e.target;if(t.dataset.pe&&pe){const f=t.dataset.pe,o=t.dataset.k===undefined?pe:pe.steps[+t.dataset.k];f==='i'?o.i=t.value.split('\n').map(x=>x.trim()).filter(Boolean):o[f]=t.value}else if(t.dataset.de&&de)de[t.dataset.de]=t.value});
