const CO=()=>{const D={name:'R.L ENERGIE',tag:'Solaire photovoltaïque',addr:'6 Le Favril',zip:'28120',city:'Blandainville',tel:'02 37 81 36 11',mail:'contact@rl-energie.fr',web:'www.rl-energie.fr',siret:'840 910 541 00027'},S=ls.get('rl_co',{});if(ls.get('rl_co_v',0)<2){['addr','zip','city','tel','siret'].forEach(k=>delete S[k]);ls.set('rl_co',S);ls.set('rl_co_v',2)}return Object.fromEntries(Object.entries(D).map(([k,v])=>[k,S[k]||v]))};
const PP=()=>ls.get('rl_pp','both'),z2=x=>String(x).padStart(2,'0');
